/**
 * 時間顯示插件
 */

import type { MpvPlugin } from '../../core/types/plugin';
import { ControlPlugin, ControlPluginOptions } from '../base/ControlPlugin';
import { formatTime } from '../../renderer/ui/utils';
import styles from './styles.css?inline';

export interface TimeDisplayPluginOptions extends ControlPluginOptions {
    /** 是否顯示總時長 */
    showDuration?: boolean;
}

export const TimeDisplayPlugin: MpvPlugin<TimeDisplayPluginOptions> = {
    name: 'timeDisplay',
    version: '1.0.0',
    styles,

    install(player, options = {}) {
        return new TimeDisplayManager(player, {
            showDuration: options.showDuration ?? true,
            position: 'progress',
            order: 0,
        });
    },
};

export class TimeDisplayManager extends ControlPlugin<Required<TimeDisplayPluginOptions & { position: 'progress'; order: number }>> {
    readonly name = 'timeDisplay';

    // DO NOT initialize these fields here! JavaScript field initializers run AFTER super(),
    // which would reset values set during createEl() back to null.
    private timeCurrent!: HTMLElement | null;
    private timeDuration!: HTMLElement | null;

    protected createEl(): HTMLElement {
        const container = document.createElement('div');
        container.className = 'vp-time-display';
        container.innerHTML = `
            <span class="vp-time-current">0:00</span>
            ${this.options.showDuration ? `
                <span class="vp-time-separator">/</span>
                <span class="vp-time-duration">0:00</span>
            ` : ''}
        `;

        this.timeCurrent = container.querySelector('.vp-time-current');
        this.timeDuration = container.querySelector('.vp-time-duration');

        // 綁定事件
        this.onPlayer('timeupdate', () => this.updateTime());
        this.onPlayer('durationchange', () => this.updateTime());
        this.onPlayer('loadedmetadata', () => this.updateTime());

        // 初始化時間顯示
        this.updateTime();

        return container;
    }

    /**
     * 覆寫插入方法，將時間顯示插入到 progress-section 的開頭
     */
    protected insertElement(): void {
        if (!this.el) return;

        const container = this.getControlsContainer();
        if (!container) return;

        // 插入到 progress-section 的開頭
        container.insertBefore(this.el, container.firstChild);
    }

    private updateTime(): void {
        if (this.timeCurrent) {
            this.timeCurrent.textContent = formatTime(this.player.currentTime);
        }
        if (this.timeDuration) {
            this.timeDuration.textContent = formatTime(this.player.duration || 0);
        }
    }
}

